1	import { db } from "../lib/db";
2	import { pve, node, waitForTask, nextVmid } from "../lib/proxmox";
3	import { allocateIp, allocateSshPort, gatewayIp } from "../lib/ipam";
4	import { syncPortForwards } from "./network";
5	import { billingSweep } from "./billing";
6	import { randomBytes } from "node:crypto";
7	import type { Job, Server } from "@prisma/client";
8	
9	const POLL_MS = 3000;
10	const MAX_ATTEMPTS = 3;
11	
12	function generatePassword(): string {
13	  // URL-safe, no ambiguous chars, 16 chars
14	  return randomBytes(24).toString("base64url").replace(/[-_]/g, "x").slice(0, 16);
15	}
16	
17	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any }> {
18	  const server = await db.server.findUnique({
19	    where: { id: job.serverId! },
20	    include: { plan: true, osTemplate: true },
21	  });
22	  if (!server) throw new Error(`Server ${job.serverId} not found`);
23	  return server;
24	}
25	
26	async function provision(job: Job) {
27	  const server = await loadServer(job);
28	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
29	
30	  const vmid = server.vmid ?? (await nextVmid());
31	  const ip = server.ipAddress ?? (await allocateIp());
32	  const sshPort = server.sshPort ?? (await allocateSshPort());
33	  const password = generatePassword();
34	
35	  await db.server.update({
36	    where: { id: server.id },
37	    data: { vmid, ipAddress: ip, sshPort, rootPassword: password },
38	  });
39	
40	  // Clone the template
41	  const cloneUpid = await pve.post(`/nodes/${node}/qemu/${server.osTemplate.vmid}/clone`, {
42	    newid: vmid,
43	    name: server.hostname,
44	    full: 1,
45	    storage: "vmdata",
46	  });
47	  await waitForTask(cloneUpid, 600_000);
48	
49	  // Apply plan resources + cloud-init (inject the owner's SSH keys if they have any)
50	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
51	  const sshkeys = keys.length
52	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
53	    : undefined;
54	  await pve.post(`/nodes/${node}/qemu/${vmid}/config`, {
55	    cores: server.plan.cpuCores,
56	    memory: server.plan.ramMB,
57	    ciuser: "root",
58	    cipassword: password,
59	    sshkeys,
60	    ipconfig0: `ip=${ip}/24,gw=${gatewayIp()}`,
61	    nameserver: "1.1.1.1 8.8.8.8",
62	    onboot: 1,
63	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
64	  });
65	
66	  // Grow the disk to plan size (template disks are ~3.5G)
67	  await pve.put(`/nodes/${node}/qemu/${vmid}/resize`, {
68	    disk: "scsi0",
69	    size: `${server.plan.diskGB}G`,
70	  });
71	
72	  await syncPortForwards();
73	
74	  const startUpid = await pve.post(`/nodes/${node}/qemu/${vmid}/status/start`, {});
75	  await waitForTask(startUpid);
76	
77	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
78	  await notify(server.userId, `Server ${server.hostname} is ready`,
79	    `SSH: ssh root@${process.env.PUBLIC_IP} -p ${sshPort}`, `/dashboard/servers/${server.id}`);
80	}
81	
82	async function powerAction(job: Job, action: "start" | "stop" | "reboot") {
83	  const server = await loadServer(job);
84	  const upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/${action}`, {});
85	  await waitForTask(upid);
86	  await db.server.update({
87	    where: { id: server.id },
88	    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
89	  });
90	}
91	
92	async function destroyVm(vmid: number) {
93	  // Stop first (ignore failure if already stopped), then destroy
94	  try {
95	    const stopUpid = await pve.post(`/nodes/${node}/qemu/${vmid}/status/stop`, {});
96	    await waitForTask(stopUpid);
97	  } catch {
98	    /* already stopped or does not exist */
99	  }
100	  const delUpid = await pve.del(`/nodes/${node}/qemu/${vmid}`, {
101	    "destroy-unreferenced-disks": 1,
102	    purge: 1,
103	  });
104	  await waitForTask(delUpid, 600_000);
105	}
106	
107	async function remove(job: Job) {
108	  const server = await loadServer(job);
109	  if (server.vmid) {
110	    try {
111	      await destroyVm(server.vmid);
112	    } catch (e: any) {
113	      // VM may never have been created; only swallow "does not exist"
114	      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
115	    }
116	  }
117	  await db.server.delete({ where: { id: server.id } });
118	  await syncPortForwards();
119	}
120	
121	async function reinstall(job: Job) {
122	  const server = await loadServer(job);
123	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
124	  if (server.vmid) await destroyVm(server.vmid);
125	  await provision(job);
126	}
127	
128	async function suspend(job: Job, unsuspend: boolean) {
129	  const server = await loadServer(job);
130	  if (unsuspend) {
131	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
132	    await syncPortForwards();
133	    const upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/start`, {});
134	    await waitForTask(upid);
135	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
136	  } else {
137	    try {
138	      const upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/stop`, {});
139	      await waitForTask(upid);
140	    } catch { /* may already be stopped */ }
141	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
142	    await syncPortForwards();
143	  }
144	}
145	
146	async function notify(userId: string, title: string, body?: string, href?: string) {
147	  try {
148	    await db.notification.create({ data: { userId, title, body, href } });
149	  } catch (e) {
150	    console.error("[worker] notify failed", e);
151	  }
152	}
153	
154	async function resize(job: Job) {
155	  const server = await loadServer(job);
156	  const payload = (job.payload ?? {}) as { planId?: string };
157	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
158	  if (!newPlan) throw new Error("resize: target plan not found");
159	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
160	
161	  const wasRunning = server.status === "RUNNING";
162	  await pve.post(`/nodes/${node}/qemu/${server.vmid}/config`, {
163	    cores: newPlan.cpuCores,
164	    memory: newPlan.ramMB,
165	  });
166	  if (newPlan.diskGB > server.plan.diskGB) {
167	    await pve.put(`/nodes/${node}/qemu/${server.vmid}/resize`, {
168	      disk: "scsi0",
169	      size: `${newPlan.diskGB}G`,
170	    });
171	  }
172	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
173	  // CPU/RAM changes need a power cycle to apply
174	  if (wasRunning) {
175	    try {
176	      const stopUpid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
177	      await waitForTask(stopUpid, 120_000);
178	    } catch {
179	      const stopUpid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/stop`, {});
180	      await waitForTask(stopUpid);
181	    }
182	    const startUpid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/start`, {});
183	    await waitForTask(startUpid);
184	  }
185	  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
186	    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${newPlan.diskGB} GB disk`,
187	    `/dashboard/servers/${server.id}`);
188	}
189	
190	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
191	  const server = await loadServer(job);
192	  const payload = (job.payload ?? {}) as { name?: string };
193	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
194	  if (!name) throw new Error("snapshot: invalid name");
195	  let upid: string;
196	  if (op === "create") {
197	    upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/snapshot`, { snapname: name });
198	  } else if (op === "delete") {
199	    upid = await pve.del(`/nodes/${node}/qemu/${server.vmid}/snapshot/${name}`);
200	  } else {
201	    upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
202	  }
203	  await waitForTask(upid, 600_000);
204	  if (op === "rollback") {
205	    // rollback leaves the VM stopped; bring it back if the server should be running
206	    const current = await db.server.findUnique({ where: { id: server.id } });
207	    if (current?.status === "RUNNING") {
208	      try {
209	        const startUpid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/start`, {});
210	        await waitForTask(startUpid);
211	      } catch { /* may already be running */ }
212	    }
213	  }
214	}
215	
216	async function backupCreate(job: Job) {
217	  const server = await loadServer(job);
218	  const upid = await pve.post(`/nodes/${node}/vzdump`, {
219	    vmid: server.vmid,
220	    storage: "backup",
221	    mode: "snapshot",
222	    compress: "zstd",
223	  });
224	  await waitForTask(upid, 3_600_000);
225	  await notify(server.userId, `Backup completed for ${server.hostname}`, undefined,
226	    `/dashboard/servers/${server.id}`);
227	}
228	
229	const handlers: Record<string, (job: Job) => Promise<void>> = {
230	  PROVISION: provision,
231	  START: (j) => powerAction(j, "start"),
232	  STOP: (j) => powerAction(j, "stop"),
233	  REBOOT: (j) => powerAction(j, "reboot"),
234	  DELETE: remove,
235	  REINSTALL: reinstall,
236	  SUSPEND: (j) => suspend(j, false),
237	  UNSUSPEND: (j) => suspend(j, true),
238	  RESIZE: resize,
239	  SNAPSHOT_CREATE: (j) => snapshotOp(j, "create"),
240	  SNAPSHOT_DELETE: (j) => snapshotOp(j, "delete"),
241	  SNAPSHOT_ROLLBACK: (j) => snapshotOp(j, "rollback"),
242	  BACKUP_CREATE: backupCreate,
243	  SYNC_FORWARDS: async () => syncPortForwards(),
244	};
245	
246	async function runJob(job: Job) {
247	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
248	  await db.job.update({
249	    where: { id: job.id },
250	    data: { status: "RUNNING", attempts: { increment: 1 } },
251	  });
252	  try {
253	    await handlers[job.type](job);
254	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
255	    console.log(`[worker] job ${job.id} DONE`);
256	  } catch (e: any) {
257	    const error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`.slice(0, 2000);
258	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
259	    const current = await db.job.findUnique({ where: { id: job.id } });
260	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
261	    await db.job.update({
262	      where: { id: job.id },
263	      data: { status: retriable ? "QUEUED" : "FAILED", error },
264	    });
265	    if (!retriable && job.serverId) {
266	      const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
267	      if (stillExists) {
268	        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
269	      }
270	    }
271	  }
272	}
273	
274	async function main() {
275	  console.log("[worker] Nxeon provisioning worker starting");
276	  await syncPortForwards();
277	  console.log("[worker] port forwards synced");
278	
279	  let lastSweep = 0;
280	  for (;;) {
281	    if (Date.now() - lastSweep > 10 * 60_000) {
282	      lastSweep = Date.now();
283	      try {
284	        await billingSweep();
285	      } catch (e) {
286	        console.error("[billing] sweep error", e);
287	      }
288	    }
289	    try {
290	      const job = await db.job.findFirst({
291	        where: { status: "QUEUED" },
292	        orderBy: { createdAt: "asc" },
293	      });
294	      if (job) {
295	        await runJob(job);
296	      } else {
297	        await new Promise((r) => setTimeout(r, POLL_MS));
298	      }
299	    } catch (e) {
300	      console.error("[worker] loop error", e);
301	      await new Promise((r) => setTimeout(r, POLL_MS));
302	    }
303	  }
304	}
305	
306	main();
