1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { requireUser } from "./auth";
7	
8	async function ownedServer(serverId: string) {
9	  const user = await requireUser();
10	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
11	  if (!server) throw new Error("Not found");
12	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
13	  return { user, server };
14	}
15	
16	async function queueJob(
17	  serverId: string,
18	  type: "SNAPSHOT_CREATE" | "SNAPSHOT_DELETE" | "SNAPSHOT_ROLLBACK" | "BACKUP_CREATE" | "RESIZE",
19	  payload?: Record<string, unknown>
20	): Promise<{ error?: string }> {
21	  const pending = await db.job.count({
22	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
23	  });
24	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
25	  await db.job.create({ data: { type, serverId, payload: payload as any } });
26	  return {};
27	}
28	
29	// ---------- Snapshots ----------
30	
31	export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
32	  const { user, server } = await ownedServer(serverId);
33	  const clean = name.replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
34	  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
35	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
36	    return { error: "Server must be running or stopped." };
37	  }
38	  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
39	  if (!res.error) {
40	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
41	    revalidatePath(`/dashboard/servers/${serverId}`);
42	  }
43	  return res;
44	}
45	
46	export async function deleteSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
47	  const { user } = await ownedServer(serverId);
48	  const res = await queueJob(serverId, "SNAPSHOT_DELETE", { name });
49	  if (!res.error) {
50	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_delete", detail: `${serverId} ${name}` } });
51	    revalidatePath(`/dashboard/servers/${serverId}`);
52	  }
53	  return res;
54	}
55	
56	export async function rollbackSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
57	  const { user } = await ownedServer(serverId);
58	  const res = await queueJob(serverId, "SNAPSHOT_ROLLBACK", { name });
59	  if (!res.error) {
60	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_rollback", detail: `${serverId} ${name}` } });
61	    revalidatePath(`/dashboard/servers/${serverId}`);
62	  }
63	  return res;
64	}
