66	// ---------- Backups ----------
67	
68	export async function createBackup(serverId: string): Promise<{ error?: string }> {
69	  const { user, server } = await ownedServer(serverId);
70	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
71	    return { error: "Server must be running or stopped." };
72	  }
73	  const res = await queueJob(serverId, "BACKUP_CREATE");
74	  if (!res.error) {
75	    await db.auditLog.create({ data: { userId: user.id, action: "server.backup_create", detail: serverId } });
76	    revalidatePath(`/dashboard/servers/${serverId}`);
77	  }
78	  return res;
79	}
80	
81	// ---------- Resize ----------
82	
83	export async function resizeServer(serverId: string, planId: string): Promise<{ error?: string }> {
84	  const { user, server } = await ownedServer(serverId);
85	  const newPlan = await db.plan.findUnique({ where: { id: planId } });
86	  if (!newPlan?.active) return { error: "Plan not available." };
87	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
88	  if (newPlan.diskGB < server.plan.diskGB) {
89	    return { error: "Disk storage can only grow — choose a plan with equal or larger disk." };
90	  }
91	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
92	  const res = await queueJob(serverId, "RESIZE", { planId });
93	  if (!res.error) {
94	    await db.auditLog.create({
95	      data: { userId: user.id, action: "server.resize", detail: `${serverId} -> ${newPlan.slug}` },
96	    });
97	    revalidatePath(`/dashboard/servers/${serverId}`);
98	  }
99	  return res;
100	}
101	
102	// ---------- Port forwarding (firewall/networking) ----------
103	
104	import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
105	const MAX_FORWARDS_PER_SERVER = 10;
106	
107	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
108	  const serverId = String(formData.get("serverId") ?? "");
109	  const { user, server } = await ownedServer(serverId);
110	  const parsed = z
111	    .object({
112	      guestPort: z.coerce.number().int().min(1).max(65535),
113	      protocol: z.enum(["tcp", "udp"]),
114	    })
115	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
116	  if (!parsed.success) return { error: "Invalid port." };
117	
118	  const count = await db.portForward.count({ where: { serverId } });
119	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
120	
121	  const used = new Set([
122	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
123	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
124	  ]);
125	  let publicPort = 0;
126	  for (let p = PF_MIN; p <= PF_MAX; p++) {
127	    if (!used.has(p)) { publicPort = p; break; }
128	  }
129	  if (!publicPort) return { error: "No public ports available." };
130	
131	  await db.portForward.create({
132	    data: { serverId, publicPort, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
133	  });
134	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
135	  await db.auditLog.create({
136	    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
137	  });
138	  revalidatePath(`/dashboard/servers/${serverId}`);
139	  return {};
140	}
141	
142	export async function deletePortForward(serverId: string, forwardId: string) {
143	  const { user } = await ownedServer(serverId);
144	  await db.portForward.deleteMany({ where: { id: forwardId, serverId } });
145	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
146	  await db.auditLog.create({
147	    data: { userId: user.id, action: "server.portforward_delete", detail: `${serverId} ${forwardId}` },
148	  });
149	  revalidatePath(`/dashboard/servers/${serverId}`);
150	}
