1	import { db } from "../lib/db";
2	
3	const GRACE_DAYS = 3;
4	const RENEW_DAYS = 30;
5	
6	/**
7	 * Subscription sweep, run periodically by the worker:
8	 *  - expired + autoRenew + sufficient balance  -> charge wallet, extend 30 days
9	 *  - expired beyond grace (or autoRenew off)   -> queue SUSPEND with unpaid note
10	 * Free servers (isFree) are never touched.
11	 */
12	export async function billingSweep() {
13	  const now = new Date();
14	
15	  // Renewal warnings: notify once when a paid server is within 3 days of expiry
16	  const soon = new Date(now.getTime() + 3 * 86400_000);
17	  const upcoming = await db.server.findMany({
18	    where: {
19	      isFree: false,
20	      expiresAt: { gt: now, lt: soon },
21	      status: { in: ["RUNNING", "STOPPED"] },
22	    },
23	    include: { plan: true, user: true },
24	  });
25	  for (const server of upcoming) {
26	    if (server.autoRenew && server.user.balanceCents >= server.plan.priceCents) continue;
27	    const already = await db.notification.findFirst({
28	      where: {
29	        userId: server.userId,
30	        title: { contains: server.hostname },
31	        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
32	        AND: { title: { contains: "renews soon" } },
33	      },
34	    });
35	    if (!already) {
36	      await db.notification.create({
37	        data: {
38	          userId: server.userId,
39	          title: `${server.hostname} renews soon — action needed`,
40	          body: server.autoRenew
41	            ? `Renewal is $${(server.plan.priceCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
42	            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
43	          href: `/dashboard/servers/${server.id}`,
44	        },
45	      });
46	    }
47	  }
48	  const due = await db.server.findMany({
49	    where: {
50	      isFree: false,
51	      expiresAt: { lt: now },
52	      status: { in: ["RUNNING", "STOPPED"] },
53	    },
54	    include: { plan: true, user: true },
55	  });
56	
57	  for (const server of due) {
58	    const graceEnd = new Date(server.expiresAt!.getTime() + GRACE_DAYS * 86400_000);
59	
60	    if (server.autoRenew && server.user.balanceCents >= server.plan.priceCents) {
61	      const newExpiry = new Date(
62	        Math.max(server.expiresAt!.getTime(), now.getTime()) + RENEW_DAYS * 86400_000
63	      );
64	      await db.$transaction([
65	        db.user.update({
66	          where: { id: server.userId },
67	          data: { balanceCents: { decrement: server.plan.priceCents } },
68	        }),
69	        db.walletTransaction.create({
70	          data: {
71	            userId: server.userId,
72	            amountCents: -server.plan.priceCents,
73	            description: `Renewal: ${server.plan.name} VPS (${server.hostname})`,
74	          },
75	        }),
76	        db.server.update({
77	          where: { id: server.id },
78	          data: { expiresAt: newExpiry },
79	        }),
80	        db.auditLog.create({
81	          data: { userId: server.userId, action: "billing.renewed", detail: server.id },
82	        }),
83	      ]);
84	      console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
85	    } else if (now > graceEnd) {
86	      const pending = await db.job.count({
87	        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
88	      });
89	      if (pending === 0) {
90	        await db.server.update({
91	          where: { id: server.id },
92	          data: { suspendedNote: "unpaid — renew from your billing page to restore access" },
93	        });
94	        await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
95	        await db.auditLog.create({
96	          data: { userId: server.userId, action: "billing.suspended_unpaid", detail: server.id },
97	        });
98	        await db.notification.create({
99	          data: {
100	            userId: server.userId,
101	            title: `${server.hostname} suspended — payment overdue`,
102	            body: "Pay from the server page to restore access instantly.",
103	            href: `/dashboard/servers/${server.id}`,
104	          },
105	        });
106	        console.log(`[billing] suspending unpaid ${server.hostname}`);
107	      }
108	    }
109	  }
110	}
