35	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
36	    email: z.string().email(),
37	  });
38	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
39	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
40	
41	  const contactParsed = contactSchema.safeParse({
42	    firstName: formData.get("firstName"),
43	    lastName: formData.get("lastName"),
44	    address1: formData.get("address1"),
45	    city: formData.get("city"),
46	    stateProvince: formData.get("stateProvince"),
47	    postalCode: formData.get("postalCode"),
48	    country: String(formData.get("country") ?? "").toUpperCase(),
49	    phone: formData.get("phone"),
50	    email: formData.get("email"),
51	  });
52	  if (!contactParsed.success) {
53	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
54	  }
55	
56	  if (await db.domain.findUnique({ where: { name: domain } })) {
57	    return { error: "This domain is already managed by another account." };
58	  }
59	
60	  // Live availability + price from name.com
61	  let priceCents: number;
62	  try {
63	    const [check] = await checkDomains([domain]);
64	    if (!check) return { error: "Could not check availability. Try again." };
65	    if (!check.available) return { error: "Domain is not available." };
66	    if (check.premium) return { error: "Premium domains are not supported yet." };
67	    if (check.priceCents === null) return { error: "No price available for this TLD." };
