104	      db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: priceCents } } }),
105	      db.walletTransaction.create({
106	        data: { userId: user.id, amountCents: priceCents, description: `Refund: failed registration ${domain}` },
107	      }),
