209	export async function deleteDnsRecord(
210	  domainId: string,
211	  record: { name: string; type: string; address: string }
212	): Promise<{ error?: string }> {
213	  let ctx;
214	  try {
215	    ctx = await ownedDomain(domainId);
216	  } catch (e: any) {
217	    return { error: e.message };
218	  }
219	  const wantHost = ["@", ""].includes(record.name) ? "" : record.name;
220	  try {
221	    const recs = await listRecords(ctx.domain.name);
222	    const match = recs.find((r) => r.host === wantHost && r.type === record.type && r.answer === record.address);
223	    if (!match) return { error: "Record not found (it may have already been removed)." };
224	    await deleteRecord(ctx.domain.name, match.id);
225	  } catch (e: any) {
226	    return { error: String(e?.message ?? e).slice(0, 200) };
227	  }
228	  revalidatePath(`/dashboard/domains/${domainId}`);
229	  return {};
230	}
