247	    await addRecord(ctx.domain.name, { host: "", type: "A", answer: ip, ttl: 300 });
248	    await addRecord(ctx.domain.name, { host: "www", type: "A", answer: ip, ttl: 300 });
249	  } catch (e: any) {
250	    return { error: String(e?.message ?? e).slice(0, 200) };
251	  }
252	  revalidatePath(`/dashboard/domains/${domainId}`);
253	  return {};
254	}
