import { db } from "./db";

/**
 * Host capacity accounting for the deploy flow.
 *
 * We oversell RAM (the scarce resource) by a factor, but never past the
 * host's physical RAM minus a reserve for the hypervisor itself. Disk on
 * `vmdata` is large relative to plan sizes, so RAM is the binding constraint.
 *
 * All values are overridable via env so staging/prod can differ without code
 * changes; the defaults match the production KS-GAME box (64 GB RAM).
 */
export const HOST_RAM_MB = Number(process.env.NXEON_HOST_RAM_MB ?? 64000);
export const HOST_RAM_RESERVE_MB = Number(process.env.NXEON_HOST_RAM_RESERVE_MB ?? 8000);
export const RAM_OVERSELL_FACTOR = Number(process.env.NXEON_RAM_OVERSELL ?? 1.5);

/** Effective committable RAM ceiling in MB after reserve + oversell. */
export function ramCeilingMB(): number {
  return Math.max(0, (HOST_RAM_MB - HOST_RAM_RESERVE_MB) * RAM_OVERSELL_FACTOR);
}

export type CapacitySnapshot = {
  committedRamMB: number;
  committedDiskGB: number;
  ceilingRamMB: number;
  serverCount: number;
  /** 0..1 fraction of the RAM ceiling already committed. */
  ramUtilization: number;
  /** true once committed RAM is within 15% of the ceiling. */
  nearCapacity: boolean;
};

/** Sum committed RAM/disk across all servers that are not being torn down. */
export async function capacitySnapshot(): Promise<CapacitySnapshot> {
  const servers = await db.server.findMany({
    where: { status: { not: "DELETING" } },
    select: { plan: { select: { ramMB: true, diskGB: true } } },
  });
  const committedRamMB = servers.reduce((sum, s) => sum + s.plan.ramMB, 0);
  const committedDiskGB = servers.reduce((sum, s) => sum + s.plan.diskGB, 0);
  const ceilingRamMB = ramCeilingMB();
  const ramUtilization = ceilingRamMB > 0 ? committedRamMB / ceilingRamMB : 1;
  return {
    committedRamMB,
    committedDiskGB,
    ceilingRamMB,
    serverCount: servers.length,
    ramUtilization,
    nearCapacity: ramUtilization >= 0.85,
  };
}

/**
 * Would deploying `planId` push committed RAM past the oversell ceiling?
 * Returns { ok:false, reason } when the host cannot take the new server.
 */
export async function capacityCheck(planId: string): Promise<{ ok: boolean; reason?: string }> {
  const plan = await db.plan.findUnique({ where: { id: planId }, select: { ramMB: true, name: true } });
  if (!plan) return { ok: false, reason: "Plan not found." };

  const snap = await capacitySnapshot();
  const projected = snap.committedRamMB + plan.ramMB;
  if (projected > snap.ceilingRamMB) {
    return {
      ok: false,
      reason:
        "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
        "Please try a smaller plan or contact support.",
    };
  }
  return { ok: true };
}

