export function FirewallPresets({
  serverId,
  disabled,
  existingGuestPorts,
}: {
  serverId: string;
  disabled?: boolean;
  existingGuestPorts: number[];
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [busyPort, setBusyPort] = useState<number | null>(null);
  const taken = new Set(existingGuestPorts);

  const add = (guestPort: number, protocol: "tcp" | "udp") => {
    setError(null);
    setBusyPort(guestPort);
    const fd = new FormData();
    fd.set("serverId", serverId);
    fd.set("guestPort", String(guestPort));
    fd.set("protocol", protocol);
    start(async () => {
      const res = await addPortForward({}, fd);
      if (res?.error) setError(res.error);
      setBusyPort(null);
    });
  };

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap gap-2">
        {PRESETS.map((p) => {
          const already = taken.has(p.guestPort);
          return (
            <button
              key={p.guestPort}
              type="button"
              className="btn-secondary px-3 py-1.5 text-sm"
              disabled={disabled || pending || already}
              title={already ? `Port ${p.guestPort} is already forwarded` : p.hint}
              onClick={() => add(p.guestPort, p.protocol)}
            >
              {busyPort === p.guestPort && pending
                ? "Adding…"
                : already
                  ? `${p.label} ✓`
                  : `Allow ${p.label} (${p.guestPort})`}
            </button>
          );
        })}
      </div>
      {error && <p className="text-sm text-red-400">{error}</p>}
