import { StatusDot, timeAgo } from "@/components/ui/primitives";

/** A job as needed by the timeline — plain data, safe from a server component. */
export type TimelineJob = {
  id: string;
  type: string;
  status: string;
  attempts: number;
  payload: unknown;
  error: string | null;
  createdAt: Date;
  updatedAt: Date;
};

const TITLES: Record<string, string> = {
  PROVISION: "Server deployed",
  START: "Powered on",
  STOP: "Powered off",
  REBOOT: "Rebooted",
  REINSTALL: "Reinstalled OS",
  DELETE: "Deleted",
  SUSPEND: "Suspended",
  UNSUSPEND: "Unsuspended",
  RESIZE: "Resized plan",
  SNAPSHOT_CREATE: "Snapshot created",
  SNAPSHOT_DELETE: "Snapshot deleted",
  SNAPSHOT_ROLLBACK: "Rolled back to snapshot",
  BACKUP_CREATE: "Backup created",
  PASSWORD_RESET: "Root password reset",
  SYNC_FORWARDS: "Networking updated",
};

/** Human-readable detail from a job's payload. */
function describePayload(type: string, payload: unknown, planNames: Record<string, string>): string | null {
  if (!payload || typeof payload !== "object") return null;
  const p = payload as Record<string, unknown>;
  if (type === "RESIZE" && typeof p.planId === "string") {
    return `→ ${planNames[p.planId] ?? "new plan"}`;
  }
  if (type.startsWith("SNAPSHOT_") && typeof p.name === "string") {
    return `“${p.name}”`;
  }
  return null;
}

function dotClass(status: string): string {
  if (status === "DONE") return "bg-emerald-400";
  if (status === "FAILED") return "bg-red-400";
  if (status === "RUNNING") return "bg-amber-400 animate-pulse-dot";
  return "bg-slate-500";
}

export function ActivityTimeline({
  jobs,
  planNames,
}: {
  jobs: TimelineJob[];
  planNames: Record<string, string>;
}) {
  if (jobs.length === 0) {
    return <p className="px-4 py-6 text-sm text-slate-400">No activity recorded for this server yet.</p>;
  }
  return (
    <ol className="relative space-y-5 px-5 py-5">
      <span className="absolute bottom-2 left-[9px] top-2 w-px bg-white/10" aria-hidden />
      {jobs.map((j) => {
        const detail = describePayload(j.type, j.payload, planNames);
        return (
          <li key={j.id} className="relative flex gap-4 pl-6">
            <span
              className={`absolute left-0 top-1.5 h-[10px] w-[10px] rounded-full ring-4 ring-navy-900 ${dotClass(j.status)}`}
              aria-hidden
            />
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
                <span className="font-medium">{TITLES[j.type] ?? j.type.toLowerCase().replace(/_/g, " ")}</span>
                {detail && <span className="font-mono text-xs text-slate-400">{detail}</span>}
                <StatusDot status={j.status} />
                {j.attempts > 1 && (
                  <span className="text-xs text-slate-500">· {j.attempts} attempts</span>
                )}
              </div>
              {j.status === "FAILED" && j.error && (
                <p className="mt-1 max-w-xl truncate text-xs text-red-400" title={j.error}>
                  {j.error}
                </p>
              )}
            </div>
            <time className="shrink-0 text-xs text-slate-500">{timeAgo(j.createdAt)}</time>
          </li>
        );
      })}
    </ol>
  );
}

